const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = Math.max(48, W * 0.08);
    var x1 = Math.min(W - 48, W * 0.92);
    if (x1 <= x0 + 60) {
      x0 = 28;
      x1 = W - 28;
    }
    var y = Math.min(Math.max(44, H * 0.56), H - 52);
    var L = x1 - x0;
    var xs = function (v) { return x0 + L * v; };
    var fs = Math.max(11, Math.min(18, W / 45));
    var labelY = y + fs * 2;
    var paths = [];
    var children = [];

    var axisCmds = visualSdk.axis({ x0: x0, y0: y, x1: x1, y1: y, ticks: 0, tickLength: 0 });
    paths.push({ id: 'axis', commands: axisCmds });
    children.push({ type: 'path', pathId: 'axis', stroke: '#26354a', strokeWidth: 2, fill: 'none' });

    var vals = [0, 1 / 3, 1 / 2, 1];
    var labels = ['0', '1/3', '1/2', '1'];
    for (var i = 0; i < vals.length; i++) {
      var x = xs(vals[i]);
      var tickId = 'tick' + i;
      paths.push({ id: tickId, commands: visualSdk.polyline([[x, y - 7], [x, y + 7]]) });
      children.push({ type: 'path', pathId: tickId, stroke: '#26354a', strokeWidth: 2, fill: 'none' });
      children.push({
        type: 'label',
        text: labels[i],
        x: x,
        y: labelY,
        fontSize: fs,
        textAnchor: 'middle',
        fill: '#26354a'
      });
    }

    var dots = [1 / 3, 1 / 2];
    for (var j = 0; j < dots.length; j++) {
      var dx = xs(dots[j]);
      var dotId = 'dot' + j;
      paths.push({ id: dotId, commands: visualSdk.circle(dx, y, 4) });
      children.push({ type: 'path', pathId: dotId, stroke: '#26354a', strokeWidth: 1, fill: '#26354a' });
    }

    return {
      schemaVersion: 1,
      sceneId: 'number-line-1-3-1-2',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
